SET NOCOUNT ON;
SET XACT_ABORT ON;

IF (SELECT COUNT(*) FROM sys.tables WHERE is_ms_shipped = 0) <> 42
BEGIN
    THROW 53000, N'Số bảng sau khi nhập không đúng.', 1;
END;

DECLARE @ExpectedRows TABLE (
    TableName sysname NOT NULL PRIMARY KEY,
    ExpectedRows bigint NOT NULL
);
INSERT INTO @ExpectedRows (TableName, ExpectedRows)
VALUES
