    (N'Feedback', 1),
    (N'Floor', 15),
    (N'Invoice', 8),
    (N'InvoiceDetail', 24),
    (N'InvoiceStatus', 4),
    (N'MaintenanceRequest', 0),
    (N'MaintenanceStatus', 4),
    (N'MeterReading', 16),
    (N'Module', 13),
    (N'Notification', 2),
    (N'NotificationReceiver', 3),
    (N'ParkingCard', 0),
    (N'ParkingSlot', 0),
    (N'Payment', 4),
