DECLARE @ActualRows TABLE (
    TableName sysname NOT NULL PRIMARY KEY,
    ActualRows bigint NOT NULL
);
DECLARE @TableName sysname;
DECLARE @ActualCount bigint;
DECLARE @Sql nvarchar(max);

DECLARE RowCheck CURSOR LOCAL FAST_FORWARD FOR
    SELECT TableName FROM @ExpectedRows ORDER BY TableName;

OPEN RowCheck;
FETCH NEXT FROM RowCheck INTO @TableName;
WHILE @@FETCH_STATUS = 0
BEGIN
    IF OBJECT_ID(N'dbo.' + @TableName, N'U') IS NULL
    BEGIN
        CLOSE RowCheck;
        DEALLOCATE RowCheck;
        THROW 53001, N'Thiếu bảng sau khi nhập.', 1;
    END;

    SET @ActualCount = NULL;
    SET @Sql = N'SELECT @CountOut = COUNT_BIG(*) FROM [dbo].' + QUOTENAME(@TableName) + N';';
    EXEC sys.sp_executesql @Sql, N'@CountOut bigint OUTPUT', @CountOut = @ActualCount OUTPUT;
    INSERT INTO @ActualRows (TableName, ActualRows) VALUES (@TableName, @ActualCount);
    FETCH NEXT FROM RowCheck INTO @TableName;
END;
CLOSE RowCheck;
DEALLOCATE RowCheck;

IF EXISTS (
    SELECT 1
    FROM @ExpectedRows AS e
    LEFT JOIN @ActualRows AS a ON a.TableName = e.TableName
    WHERE a.ActualRows IS NULL OR a.ActualRows <> e.ExpectedRows
)
BEGIN
    THROW 53002, N'Số dòng dữ liệu sau khi nhập không đúng.', 1;
END;

SELECT
    CAST(SERVERPROPERTY(N'ServerName') AS nvarchar(128)) AS ServerName,
    DB_NAME() AS DatabaseName,
    (SELECT COUNT(*) FROM sys.tables WHERE is_ms_shipped = 0) AS UserTableCount,
    (SELECT SUM(ActualRows) FROM @ActualRows) AS ImportedRowCount,
    N'NHAP DATABASE LOCAL THANH CONG' AS Result;

SELECT e.TableName, e.ExpectedRows, a.ActualRows
FROM @ExpectedRows AS e
INNER JOIN @ActualRows AS a ON a.TableName = e.TableName
ORDER BY e.TableName;
GO

SET NOEXEC OFF;
GO
